#include <stdio.h>
int main(){
    int cpus = 4;
    int load[4] = {3,5,2,4};
    int max = load[0];
    int sum = 0;
    for(int i=0;i<cpus;i++){
        if(load[i]>max) max = load[i];
        sum += load[i];
    }
    double avg = sum/(double)cpus;
    printf("Imbalance = %.2f\n", max/avg);
    return 0;
}

public class SchedCheck {
    public static void main(String[] args) {
        double[] C = {1,2,2}; // ms
        double[] T = {5,10,20}; // ms
        double U = 0;
        for(int i=0;i<C.length;i++) U += C[i]/T[i];
        System.out.printf("Total utilization = %.3f\n", U);
    }
}

